            //Called from within a workflow class
            Email EmailMessage = new Email(log);
            EmailMessage.Subject = "Short Pick By User: " + UserSession.SessionUser.LoginName;
            EmailMessage.MessageText = "Order: " +
                    OrderNumber + " was short picked by user: " +
                    UserSession.SessionUser.LoginName;
            EmailMessage.SendErpErrors();

